public static class MessageDispatchReference {
 public const string SourceSha256="c2739f468fc9610edf822ca09506bc7d9b04156035a0b935493a460fff23c39d";
 public const string ReceiverSourceSha256="e2f108f33c35ea1e579cd60a0754d22d5d124ab54161375d836503b6772aa44a";
