 private static readonly Dictionary<string,(string Error,string Data)> Expected=Load();
 private static Dictionary<string,(string Error,string Data)> Load(){using var memory=new MemoryStream(Convert.FromBase64String(""));using var gzip=new GZipStream(memory,CompressionMode.Decompress);using var reader=new StreamReader(gzip);var result=new Dictionary<string,(string,string)>();foreach(var line in reader.ReadToEnd().Split('\n')){var parts=line.Split('|');if(parts.Length!=3)throw new InvalidOperationException("Corrupt message dispatch reference");result.Add(parts[0],(parts[1],parts[2]));}return result;}
 public static string Compare(MessageDispatchCorpus.Observation row){if(!Expected.TryGetValue(row.index+"."+row.profile,out var expected))return "Unexpected query case";if(row.error!=expected.Error)return "Expected exception "+expected.Error+", actual "+row.error;if(row.data!=expected.Data)return "Expected "+expected.Data+", actual "+row.data;return "";}
}
